import stripe
import requests

def _cancel_upgrade_subscription(client, charge_id):
    # A fully refunded storage upgrade should not keep billing: cancel its subscription.
    charge = client.charges.retrieve(charge_id)
    if charge.invoice:
        invoice = client.invoices.retrieve(charge.invoice)
        sub_id = getattr(invoice, 'subscription', None)
        if sub_id:
            client.subscriptions.cancel(sub_id)

def refund_storage_upgrade_charge(charge_id: str, amount_cents: int=None) -> dict:
    refund_params = {'charge': charge_id, 'reason': 'requested_by_customer'}
    if amount_cents is not None:
        refund_params['amount'] = amount_cents
    with stripe.StripeClient(stripe.api_key, http_client=stripe.RequestsClient()) as client:
        refund = client.refunds.create(params=refund_params)
        if amount_cents is None:
            _cancel_upgrade_subscription(client, charge_id)
    return {'refund_id': refund.id, 'status': refund.status, 'amount': refund.amount}
